import{_ as s,o as r,c as o,a3 as e,j as t}from"./chunks/framework.Cc-oPviL.js";const g=JSON.parse('{"title":"02 · 注意力与 Transformer：模型怎么「看上下文」","description":"","frontmatter":{},"headers":[],"relativePath":"ai/llm/02.md","filePath":"ai/llm/02.md"}'),l={name:"ai/llm/02.md"};function i(d,a,n,h,c,x){return r(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="_02-·-注意力与-transformer-模型怎么「看上下文」" tabindex="-1">02 · 注意力与 Transformer：模型怎么「看上下文」 <a class="header-anchor" href="#_02-·-注意力与-transformer-模型怎么「看上下文」" aria-label="Permalink to &quot;02 · 注意力与 Transformer：模型怎么「看上下文」&quot;">​</a></h1><blockquote><p><strong>学完你能说出</strong>：</p><ul><li>注意力就是「处理每个词时，决定该重点看句子里的哪些词」。</li><li>Q、K、V 分别是什么（用「图书馆查书」讲清楚）。</li><li>Transformer 为什么取代了 RNN：能并行、看得远。</li></ul></blockquote><h2 id="先看地图" tabindex="-1">先看地图 <a class="header-anchor" href="#先看地图" aria-label="Permalink to &quot;先看地图&quot;">​</a></h2><p>上一篇说模型「看完前文再猜下一个字」。这一篇讲<strong>怎么看</strong>。</p><p>本篇讲 4 个点：① 注意力在解决什么问题 → ② Q/K/V 怎么算出「看谁」 → ③ 多头注意力和位置编码 → ④ 为什么 Transformer 取代了 RNN。</p><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p><strong>注意力（Attention）= 给句子里每个词打一个「我该多关注你」的分数，再按分数把大家的信息加权混合。</strong></p><h2 id="生活类比-开会时听谁的" tabindex="-1">生活类比：开会时听谁的 <a class="header-anchor" href="#生活类比-开会时听谁的" aria-label="Permalink to &quot;生活类比：开会时听谁的&quot;">​</a></h2><p>你在会上想搞清楚「这个方案谁负责」：</p><ul><li>你不会平均听每个人说话，而是<strong>重点听项目经理和你的直属领导</strong>，其他人的话权重很低；</li><li>换个问题，比如「预算多少」，你会转而重点听财务。</li></ul><p>注意力也是这样：<strong>同一个词，问的问题不同，关注的对象就不同。</strong></p><h2 id="一步步看-「它」指的是谁" tabindex="-1">一步步看：「它」指的是谁？ <a class="header-anchor" href="#一步步看-「它」指的是谁" aria-label="Permalink to &quot;一步步看：「它」指的是谁？&quot;">​</a></h2><p>句子：「小猫没吃鱼，因为它饱了。」模型处理到「它」时，要搞清楚「它」指谁。</p>',13),t("figure",{class:"fig"},[t("span",{class:"fig-hint"},"← 左右滑动看完整图 →"),t("svg",{viewBox:"0 0 680 250",width:"100%",xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"注意力权重示意"},[t("defs",null,[t("marker",{id:"arw-att",viewBox:"0 0 10 10",markerWidth:"9",markerHeight:"9",refX:"8.5",refY:"5",markerUnits:"userSpaceOnUse",orient:"auto"},[t("path",{d:"M2 1.5 L8 5 L2 8.5",class:"f-line",fill:"none","stroke-linecap":"round","stroke-linejoin":"round"})])]),t("text",{class:"f-label",x:"20",y:"24"},"处理「它」这个词时，它去「看」句子里每个词的程度（权重加起来 = 1）"),t("rect",{class:"f-box-hi",x:"30",y:"150",width:"56",height:"40",rx:"8"}),t("text",{class:"f-title",x:"58.0",y:"175.0","text-anchor":"middle"},"小猫"),t("rect",{class:"f-box-hi",x:"44",y:"47.0",width:"28",height:"93.0",rx:"3"}),t("text",{class:"f-mono",x:"58",y:"41.0","text-anchor":"middle"},"0.62"),t("rect",{class:"f-box",x:"100",y:"150",width:"56",height:"40",rx:"8"}),t("text",{class:"f-title",x:"128.0",y:"175.0","text-anchor":"middle"},"没"),t("rect",{class:"f-box",x:"114",y:"137.0",width:"28",height:"3.0",rx:"3"}),t("text",{class:"f-mono",x:"128",y:"131.0","text-anchor":"middle"},"0.02"),t("rect",{class:"f-box",x:"170",y:"150",width:"56",height:"40",rx:"8"}),t("text",{class:"f-title",x:"198.0",y:"175.0","text-anchor":"middle"},"吃"),t("rect",{class:"f-box",x:"184",y:"131.0",width:"28",height:"9.0",rx:"3"}),t("text",{class:"f-mono",x:"198",y:"125.0","text-anchor":"middle"},"0.06"),t("rect",{class:"f-box",x:"240",y:"150",width:"56",height:"40",rx:"8"}),t("text",{class:"f-title",x:"268.0",y:"175.0","text-anchor":"middle"},"鱼"),t("rect",{class:"f-box",x:"254",y:"113.0",width:"28",height:"27.0",rx:"3"}),t("text",{class:"f-mono",x:"268",y:"107.0","text-anchor":"middle"},"0.18"),t("rect",{class:"f-box",x:"310",y:"150",width:"56",height:"40",rx:"8"}),t("text",{class:"f-title",x:"338.0",y:"175.0","text-anchor":"middle"},"，"),t("text",{class:"f-mono",x:"338",y:"134.0","text-anchor":"middle"},"0.00"),t("rect",{class:"f-box",x:"380",y:"150",width:"56",height:"40",rx:"8"}),t("text",{class:"f-title",x:"408.0",y:"175.0","text-anchor":"middle"},"因为"),t("rect",{class:"f-box",x:"394",y:"135.5",width:"28",height:"4.5",rx:"3"}),t("text",{class:"f-mono",x:"408",y:"129.5","text-anchor":"middle"},"0.03"),t("rect",{class:"f-box-hi",x:"450",y:"150",width:"56",height:"40",rx:"8"}),t("text",{class:"f-title",x:"478.0",y:"175.0","text-anchor":"middle"},"它"),t("rect",{class:"f-box",x:"464",y:"132.5",width:"28",height:"7.5",rx:"3"}),t("text",{class:"f-mono",x:"478",y:"126.5","text-anchor":"middle"},"0.05"),t("rect",{class:"f-box",x:"520",y:"150",width:"56",height:"40",rx:"8"}),t("text",{class:"f-title",x:"548.0",y:"175.0","text-anchor":"middle"},"饱"),t("rect",{class:"f-box",x:"534",y:"135.5",width:"28",height:"4.5",rx:"3"}),t("text",{class:"f-mono",x:"548",y:"129.5","text-anchor":"middle"},"0.03"),t("rect",{class:"f-box",x:"590",y:"150",width:"56",height:"40",rx:"8"}),t("text",{class:"f-title",x:"618.0",y:"175.0","text-anchor":"middle"},"了"),t("rect",{class:"f-box",x:"604",y:"138.5",width:"28",height:"1.5",rx:"3"}),t("text",{class:"f-mono",x:"618",y:"132.5","text-anchor":"middle"},"0.01"),t("text",{class:"f-label",x:"30",y:"222"},"「它」最关注「小猫」（0.62），所以模型知道「它」= 小猫，而不是鱼。"),t("text",{class:"f-label",x:"30",y:"240"},"数字是示意，真实模型里有很多个注意力头，各自关注不同关系。")]),t("figcaption",{class:"fig-cap"},"注意力（Attention）就是「看重谁」：处理每个词时，给句子里所有词打一个权重，按权重把它们的信息加起来。所以同一个「它」在不同句子里能指向不同的东西——上下文决定意思。")],-1),e('<p>注意力给每个词打的权重（示意数字）：小猫 0.62、鱼 0.18、吃 0.06……<strong>加起来等于 1</strong>。于是「它」的新表示里，大部分信息来自「小猫」。模型因此「理解」了它 = 小猫。</p><p>如果句子改成「小猫没吃鱼，因为<strong>它</strong>臭了」，权重就会偏向「鱼」。<strong>上下文决定意思</strong>，这正是注意力的价值。</p><h3 id="分数是怎么算出来的-q、k、v" tabindex="-1">分数是怎么算出来的：Q、K、V <a class="header-anchor" href="#分数是怎么算出来的-q、k、v" aria-label="Permalink to &quot;分数是怎么算出来的：Q、K、V&quot;">​</a></h3><p>用<strong>图书馆查书</strong>来理解。每个词都会生成三样东西：</p><table tabindex="0"><thead><tr><th>名字</th><th>类比</th><th>作用</th></tr></thead><tbody><tr><td><strong>Q（Query，查询）</strong></td><td>你手里的「借书需求」</td><td>我现在想找什么信息</td></tr><tr><td><strong>K（Key，键）</strong></td><td>每本书的「标签」</td><td>我能提供什么信息</td></tr><tr><td><strong>V（Value，值）</strong></td><td>书的「内容」</td><td>真正被取走的信息</td></tr></tbody></table><p>计算分三步（用 2 个词的小例子）：</p><ol><li><strong>算匹配度</strong>：拿「它」的 Q 和每个词的 K 做点积（对应位置相乘再相加）。假设「它·小猫」= 4，「它·鱼」= 1。</li><li><strong>变成权重</strong>：用 softmax（把一组分数变成「都为正、加起来为 1」的比例）换算：4 和 1 → 约 0.95 和 0.05。</li><li><strong>加权混合</strong>：新的「它」= 0.95 × 小猫的 V + 0.05 × 鱼的 V。</li></ol><p>公式写出来就是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Attention(Q, K, V) = softmax( Q·Kᵀ / √d ) · V</span></span></code></pre></div><p><code>√d</code>（d 是向量长度）用来把分数缩小一点，原因见下面「为什么」。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么要注意力-而不是平均看所有词" tabindex="-1">为什么要注意力，而不是平均看所有词？ <a class="header-anchor" href="#为什么要注意力-而不是平均看所有词" aria-label="Permalink to &quot;为什么要注意力，而不是平均看所有词？&quot;">​</a></h3><ul><li><strong>问题</strong>：平均混合会把关键信息稀释掉。「它」要靠「小猫」来定义，跟「因为」「了」关系不大。</li><li><strong>方案</strong>：让模型自己学会给每个词打分，相关的分高、无关的分低。</li><li><strong>好处</strong>：同一个词在不同上下文里能得到不同的含义；而且离得很远的词也能直接关注到。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>因为不同词对理解当前词的贡献不同，注意力让模型按相关程度加权混合信息，所以能处理指代、歧义这种依赖上下文的问题。</p></div><h3 id="为什么要除以-√d" tabindex="-1">为什么要除以 √d？ <a class="header-anchor" href="#为什么要除以-√d" aria-label="Permalink to &quot;为什么要除以 √d？&quot;">​</a></h3><ul><li><strong>问题</strong>：向量越长，点积的数值越大。数值太大时，softmax 会变得「一家独大」（比如 0.999 和 0.001），梯度几乎为 0，模型就学不动了。</li><li><strong>方案</strong>：除以 √d，把分数拉回到合适的范围。</li><li><strong>好处</strong>：训练更稳定。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>防止向量维度大时点积过大，导致 softmax 饱和、梯度消失，起到稳定训练的作用。</p></div><h3 id="为什么要「多头」注意力" tabindex="-1">为什么要「多头」注意力？ <a class="header-anchor" href="#为什么要「多头」注意力" aria-label="Permalink to &quot;为什么要「多头」注意力？&quot;">​</a></h3><ul><li><strong>问题</strong>：一组 Q/K/V 只能学一种「关注方式」。但理解句子需要同时看多种关系：指代、语法、语义……</li><li><strong>方案</strong>：同时开很多组（比如 8 组、32 组），每组叫一个<strong>头（head）</strong>，各学各的关注方式，最后拼起来。</li><li><strong>好处</strong>：一个头专门找指代，另一个头专门看搭配，信息更全面。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>多头让模型在不同的子空间里同时学习多种关注关系，比单一的注意力表达能力更强。</p></div><h3 id="为什么需要位置编码" tabindex="-1">为什么需要位置编码？ <a class="header-anchor" href="#为什么需要位置编码" aria-label="Permalink to &quot;为什么需要位置编码？&quot;">​</a></h3><ul><li><strong>问题</strong>：注意力本身只看「谁和谁相关」，<strong>不管顺序</strong>。「狗咬人」和「人咬狗」在它眼里是同一堆词。</li><li><strong>方案</strong>：给每个位置加一个<strong>位置编码（Positional Encoding）</strong>，把「我是第几个词」的信息加进去。</li><li><strong>好处</strong>：模型能区分词序。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>因为注意力计算对顺序不敏感，必须额外注入位置信息，模型才能区分「狗咬人」和「人咬狗」。</p></div><h3 id="为什么-transformer-取代了-rnn" tabindex="-1">为什么 Transformer 取代了 RNN？ <a class="header-anchor" href="#为什么-transformer-取代了-rnn" aria-label="Permalink to &quot;为什么 Transformer 取代了 RNN？&quot;">​</a></h3><p><strong>RNN（循环神经网络）</strong> 是之前的主流做法：一个词一个词地顺序读，前面的信息靠一个「记忆」往后传。</p><table tabindex="0"><thead><tr><th></th><th>RNN</th><th>Transformer</th></tr></thead><tbody><tr><td>怎么读</td><td>一个一个按顺序读</td><td>所有词同时看</td></tr><tr><td>能不能并行</td><td>不能，必须等前一个算完</td><td>能，GPU 一次算完</td></tr><tr><td>远距离关系</td><td>要传很多步，信息会衰减</td><td>任意两个词一步直达</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>RNN 必须顺序计算、远距离信息容易丢；Transformer 用注意力让任意两个词直接交互，并且可以并行训练，所以能把模型做大。</p></div><h2 id="英文术语拆解" tabindex="-1">英文术语拆解 <a class="header-anchor" href="#英文术语拆解" aria-label="Permalink to &quot;英文术语拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>拆开看</th><th>一句话意思</th></tr></thead><tbody><tr><td>Attention</td><td>注意、关注</td><td>按相关程度给其他词打分并加权混合</td></tr><tr><td>Self-Attention</td><td>self 自己 + attention</td><td>自注意力：一句话内部的词互相关注</td></tr><tr><td>Query / Key / Value</td><td>查询 / 钥匙、键 / 值</td><td>「我要找什么」/「我有什么标签」/「我的内容」</td></tr><tr><td>softmax</td><td>soft 柔和的 + max 最大值</td><td>把一组分数变成加起来为 1 的概率</td></tr><tr><td>Multi-Head</td><td>multi 多 + head 头</td><td>多组注意力并行，各学一种关系</td></tr><tr><td>Positional Encoding</td><td>positional 位置的 + encoding 编码</td><td>把「第几个词」的信息加进去</td></tr><tr><td>Transformer</td><td>transform 变换 + -er 「…的东西」</td><td>以注意力为核心的模型结构，2017 年提出</td></tr><tr><td>RNN</td><td>Recurrent 循环的 + Neural Network 神经网络</td><td>按顺序逐个处理词的旧结构</td></tr></tbody></table><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：讲一下自注意力的计算过程。</strong></p><blockquote><p>每个 Token 通过三个矩阵得到 Q、K、V；用 Q 和所有 K 做点积得到相关性分数，除以 √d 缩放后过 softmax 得到权重，再用权重对 V 加权求和，得到这个 Token 融合了上下文的新表示。</p></blockquote><p><strong>Q：为什么要除以 √d？</strong></p><blockquote><p>维度大时点积方差大，softmax 会进入饱和区，梯度很小、训练不稳定。除以 √d 让分数的尺度和维度无关。</p></blockquote><p><strong>Q：Transformer 相比 RNN 的优势是什么？</strong></p><blockquote><p>一是可以并行计算，训练效率高；二是任意两个位置之间的路径长度为 1，长距离依赖更容易建模。代价是注意力的计算量随序列长度平方增长，所以上下文窗口有上限。</p></blockquote><h2 id="容易混的地方" tabindex="-1">容易混的地方 <a class="header-anchor" href="#容易混的地方" aria-label="Permalink to &quot;容易混的地方&quot;">​</a></h2><ul><li><strong>注意力权重 ≠ 模型的「理解」</strong>：它是一种信息混合方式。说「模型关注了小猫」是方便理解的说法。</li><li><strong>Q、K、V 不是三份不同的输入</strong>：它们都由同一个词的向量，乘以三个不同的（训练出来的）矩阵得到。</li><li><strong>上下文窗口有上限</strong>：注意力要算「每个词 × 每个词」，长度翻倍，计算量约变成 4 倍。</li></ul><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>← 来自</strong> <a href="/study-hub/ai/llm/01">大模型在做什么</a>：「看完前文再猜」靠的就是这里的注意力。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/llm/03">Embedding</a>：每个词进注意力之前，先要变成向量。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/llm/04">Prompt 与采样参数</a>：上下文窗口为什么有上限，源头在注意力的平方计算量。</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：用「开会听谁的」类比，解释注意力在做什么。</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>开会时你不会平均听所有人，而是根据当前问题重点听相关的人。注意力也一样：处理每个词时，给句子里每个词打分，相关的权重高，再按权重把信息混合起来。问题不同，关注的对象就不同。</p></details><p><strong>Q2：Q、K、V 分别是什么？用图书馆类比说一下。</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>Q 是「借书需求」（我想找什么），K 是每本书的「标签」（我能提供什么），V 是书的「内容」。用 Q 和每个 K 算匹配度 → softmax 变成权重 → 按权重把各本书的 V 加起来。</p></details><p><strong>Q3：为什么注意力需要位置编码？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>注意力只看词和词之间的相关性，对顺序不敏感，「狗咬人」和「人咬狗」算出来一样。加入位置编码，模型才知道每个词排在第几个。</p></details><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能用「它指谁」的例子，讲清注意力权重的作用</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能用图书馆类比说出 Q、K、V 各自是什么</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说出注意力计算的三步：点积 → softmax → 加权求和</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能讲清除以 √d、多头、位置编码各自解决什么问题（问题 → 方案 → 好处）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能对比 RNN 和 Transformer 的两个关键区别</li></ul><h2 id="下一步该懂什么" tabindex="-1">下一步该懂什么 <a class="header-anchor" href="#下一步该懂什么" aria-label="Permalink to &quot;下一步该懂什么&quot;">​</a></h2><ul><li>词是怎么变成向量的？向量之间怎么算「像不像」？→ <a href="/study-hub/ai/llm/03">Embedding：把文字变成坐标</a></li><li>想看原论文：<em>Attention Is All You Need</em>（2017），只读摘要和图 1 就够了。</li></ul>',51)])])}const u=s(l,[["render",i]]);export{g as __pageData,u as default};
